package vault

import (
	"encoding/json"
	"os"
	"reflect"
	"strings"
	"testing"
)

// The vectors are generated by the TypeScript implementation (pnpm vectors at the repo root).
type vectors struct {
	ServiceToken string `json:"serviceToken"`
	TokenFields  struct {
		U string `json:"u"`
		T string `json:"t"`
		W string `json:"w"`
		R string `json:"r"`
	} `json:"tokenFields"`
	Environment struct {
		TenantID      string            `json:"tenantId"`
		Project       string            `json:"project"`
		Name          string            `json:"name"`
		AAD           string            `json:"aad"`
		WrappedEnvDek string            `json:"wrappedEnvDek"`
		Payload       SealedBox         `json:"payload"`
		Expected      map[string]string `json:"expected"`
	} `json:"environment"`
	MustFail struct {
		WrongAAD           string    `json:"wrongAad"`
		BadVersion         SealedBox `json:"badVersion"`
		TamperedCiphertext SealedBox `json:"tamperedCiphertext"`
	} `json:"mustFail"`
}

func load(t *testing.T) vectors {
	t.Helper()
	b, err := os.ReadFile("../../testdata/zk-6.json")
	if err != nil {
		t.Fatal(err)
	}
	var v vectors
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func TestDecodeTokenVector(t *testing.T) {
	v := load(t)
	tok, err := DecodeToken(v.ServiceToken)
	if err != nil {
		t.Fatal(err)
	}
	if tok.U != v.TokenFields.U || tok.T != v.TokenFields.T || tok.W != v.TokenFields.W || tok.R != v.TokenFields.R {
		t.Fatalf("token fields differ: %v", tok)
	}
}

func TestDecodeTokenRejects(t *testing.T) {
	for _, in := range []string{"", "abc", "evt_", "evt_!!!", "evt_e30"} {
		if _, err := DecodeToken(in); err == nil {
			t.Errorf("accepted %q", in)
		}
	}
}

func TestTokenStringHidesCredentials(t *testing.T) {
	tok := Token{U: "svc", T: "secret-bearer", K: "secret-key"}
	s := tok.String()
	if s != "service-token(svc)" {
		t.Fatalf("unexpected: %s", s)
	}
}

func TestOpenEnvVector(t *testing.T) {
	v := load(t)
	tok, _ := DecodeToken(v.ServiceToken)
	e := v.Environment
	dek, err := UnwrapDEK(e.WrappedEnvDek, tok.K)
	if err != nil {
		t.Fatal(err)
	}
	if got := EnvAAD(e.TenantID, e.Project, e.Name); got != e.AAD {
		t.Fatalf("aad: %q != %q", got, e.AAD)
	}
	got, err := OpenEnv(e.Payload, dek, e.AAD)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got, e.Expected) {
		t.Fatalf("plaintext differs: %v", got)
	}
}

func TestOpenEnvMustFail(t *testing.T) {
	v := load(t)
	tok, _ := DecodeToken(v.ServiceToken)
	e := v.Environment
	dek, _ := UnwrapDEK(e.WrappedEnvDek, tok.K)
	if _, err := OpenEnv(e.Payload, dek, v.MustFail.WrongAAD); err == nil {
		t.Error("opened with the wrong location")
	}
	if _, err := OpenEnv(v.MustFail.BadVersion, dek, e.AAD); err == nil {
		t.Error("accepted version 2")
	}
	if _, err := OpenEnv(v.MustFail.TamperedCiphertext, dek, e.AAD); err == nil {
		t.Error("accepted tampered ciphertext")
	}
}

func TestUnwrapWithWrongKeyFails(t *testing.T) {
	v := load(t)
	if _, err := UnwrapDEK(v.Environment.WrappedEnvDek, "bm90LWEta2V5"); err == nil {
		t.Error("unwrapped with garbage key")
	}
}

func TestSealEnvRoundTripsAndBindsLocation(t *testing.T) {
	dek := make([]byte, 32)
	for i := range dek {
		dek[i] = byte(i)
	}
	in := map[string]string{"B": "two", "A": "one <&> \"quoted\"", "UNICODE": "héllo ✓"}
	aad := EnvAAD("t", "p", "e")
	box, err := SealEnv(in, dek, aad)
	if err != nil {
		t.Fatal(err)
	}
	if box.V != 1 || len(box.IV) != 16 || strings.ContainsAny(box.IV+box.CT, "+/=") {
		t.Fatalf("not the wire format: %+v", box)
	}
	out, err := OpenEnv(box, dek, aad)
	if err != nil || len(out) != 3 || out["A"] != in["A"] || out["UNICODE"] != in["UNICODE"] {
		t.Fatalf("round trip failed: %v %v", out, err)
	}
	if _, err := OpenEnv(box, dek, EnvAAD("t", "p", "other")); err == nil {
		t.Fatal("a payload sealed for one environment opened as another")
	}
	again, _ := SealEnv(in, dek, aad)
	if again.IV == box.IV || again.CT == box.CT {
		t.Fatal("the IV must be fresh every time")
	}
}
